#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod app;
mod ui;

use eframe::egui;
use std::path::PathBuf;

fn main() -> eframe::Result<()> {
    let mut args = std::env::args_os().skip(1);
    let mut screenshot = None;
    let mut files = Vec::new();
    while let Some(arg) = args.next() {
        if arg == "--screenshot" {
            screenshot = args.next().map(PathBuf::from);
        } else {
            files.push(PathBuf::from(arg));
        }
    }

    let mut viewport = egui::ViewportBuilder::default()
        .with_title("Cutline")
        .with_app_id("cutline")
        .with_inner_size([1360.0, 860.0])
        .with_min_inner_size([1060.0, 680.0])
        .with_icon(app_icon())
        .with_drag_and_drop(true);
    if screenshot.is_some() {
        viewport = viewport.with_active(false);
        #[cfg(windows)]
        {
            viewport = viewport.with_window_level(egui::WindowLevel::AlwaysOnBottom);
        }
    }

    #[allow(unused_mut)]
    let mut options = eframe::NativeOptions {
        viewport,
        renderer: eframe::Renderer::Glow,
        persist_window: screenshot.is_none(),
        ..Default::default()
    };
    #[cfg(target_os = "macos")]
    if screenshot.is_some() {
        options.event_loop_builder = Some(Box::new(|builder| {
            use winit::platform::macos::EventLoopBuilderExtMacOS;
            builder.with_activate_ignoring_other_apps(false);
        }));
    }

    eframe::run_native(
        "Cutline",
        options,
        Box::new(move |cc| Ok(Box::new(app::App::new(cc, files, screenshot)))),
    )
}

/// A small film frame, drawn here so there's no image file to ship.
fn app_icon() -> egui::IconData {
    const SIZE: u32 = 64;
    let mut rgba = Vec::with_capacity((SIZE * SIZE * 4) as usize);
    for y in 0..SIZE {
        for x in 0..SIZE {
            let edge = x.min(SIZE - 1 - x).min(y).min(SIZE - 1 - y);
            let t = (x + y) as f32 / (2 * SIZE) as f32;
            let body = [(110.0 - 40.0 * t) as u8, (123.0 + 70.0 * t) as u8, (255.0 - 40.0 * t) as u8, 255];
            let hole = (6..12).contains(&y) || (52..58).contains(&y);
            let pixel = if edge < 2 {
                [0, 0, 0, 0]
            } else if hole && (x / 9) % 2 == 0 {
                [16, 18, 22, 255]
            } else {
                body
            };
            rgba.extend_from_slice(&pixel);
        }
    }
    egui::IconData { rgba, width: SIZE, height: SIZE }
}

//! Everything the window draws. Each panel is a set of `App` methods in its own file.

pub mod console;
pub mod media_panel;
pub mod output_panel;
pub mod preview_panel;
pub mod theme;
pub mod timeline;

//! The "View console" panel: every FFmpeg command and its output as it runs.

use super::theme::*;
use crate::app::App;
use cutline::log::LogKind;
use eframe::egui::{self, RichText, Ui};

impl App {
    pub fn console_panel(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            ui.label(RichText::new("Console").strong());
            ui.label(RichText::new("the FFmpeg commands, as they run").size(12.0).color(FAINT));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if soft_button(ui, "Clear").clicked() {
                    self.console.clear();
                }
                if soft_button(ui, "Copy all").clicked() {
                    let text: Vec<&str> = self.console.iter().map(|line| line.text.as_str()).collect();
                    ui.ctx().copy_text(text.join("\n"));
                    self.toast("Copied the console");
                }
            });
        });
        egui::Frame::new().fill(BG).corner_radius(8.0).inner_margin(10.0).show(ui, |ui| {
            ui.set_min_size(ui.available_size());
            egui::ScrollArea::both().auto_shrink(false).stick_to_bottom(true).show(ui, |ui| {
                ui.style_mut().spacing.item_spacing.y = 3.0;
                if self.console.is_empty() {
                    ui.label(RichText::new("Commands appear here as they run.").monospace().color(FAINT));
                }
                for line in &self.console {
                    let text = RichText::new(line.text.as_str()).monospace();
                    let styled = match line.kind {
                        LogKind::Command => RichText::new(format!("$ {}", line.text)).monospace().color(ACCENT_HOVER).strong(),
                        LogKind::Info => text.color(TEXT),
                        LogKind::Output => text.color(MUTED),
                        LogKind::Warning => text.color(WARN),
                        LogKind::Error => text.color(BAD),
                        LogKind::Success | LogKind::Live => text.color(GOOD),
                    };
                    ui.add(egui::Label::new(styled).wrap_mode(egui::TextWrapMode::Extend).selectable(true));
                }
            });
        });
    }
}

